module.exports = [
{ e: "🌳", art: { b: "🌳", s: ["🐒", "🦜", "🌧️", "🍃"], c: ["#0B4E1B", "#2CA03A"] },
pt: { h: "O vovô levou Nina e Leo a um parque com árvores tão altas que o céu quase sumia. Estava fresquinho, úmido e cheio de sons de passarinhos. “Imaginem uma floresta assim do tamanho de muitos países juntos”, disse ele. “Essa é a Amazônia.”", t: "As florestas", f: "As florestas são lares para uma quantidade enorme de plantas e animais. As florestas tropicais, como a Amazônia, cobrem uma parte pequena da terra do planeta, mas abrigam mais da metade das espécies terrestres conhecidas. Elas também guardam carbono, produzem chuva e protegem rios e solos.", x: "Uma única árvore grande da Amazônia pode soltar centenas de litros de água no ar num só dia! Juntas, as árvores ajudam a fazer chover em lugares bem distantes.", s: ["A Amazônia é a maior floresta tropical do mundo e se espalha por nove países.", "As florestas têm andares: o chão, os arbustos, as copas das árvores e as árvores gigantes que passam por cima de todas.", "Cortar e queimar florestas prejudica os animais, as pessoas que vivem nelas e o clima do planeta."], ex: { t: "Floresta no pote", m: "um pote de vidro grande com tampa, pedrinhas, terra, plantinhas pequenas ou musgo, um pouco de água", p: ["Coloque uma camada de pedrinhas no fundo do pote e terra por cima.", "Plante as mudinhas ou o musgo e borrife um pouco de água.", "Feche o pote e deixe num lugar claro, mas sem sol direto. A água evapora, escorre pelo vidro e volta para a terra: é um mini ciclo da floresta!"] }, at: "Andares da floresta", m: "papel comprido, lápis de cor", p: ["Desenhe uma floresta com quatro andares, do chão até o topo das árvores mais altas.", "Coloque em cada andar animais que vivem ali: formigas, onças, macacos, araras e harpias.", "Desenhe o selo do dia 21 no passaporte."], q: "Que animal da floresta você gostaria de ver de perto?" },
en: { h: "Grandpa took Nina and Leo to a park with trees so tall the sky almost disappeared. It was cool, damp and full of birdsong. “Imagine a forest like this the size of many countries together,” he said. “That's the Amazon.”", t: "Forests", f: "Forests are home to an enormous number of plants and animals. Tropical rainforests, like the Amazon, cover a small part of the planet's land but shelter more than half of known land species. They also store carbon, make rain and protect rivers and soil.", x: "A single big Amazon tree can release hundreds of liters of water into the air in one day! Together, trees help make it rain in places far away.", s: ["The Amazon is the world's largest tropical rainforest and stretches across nine countries.", "Forests have floors: the ground, the shrubs, the tree canopy and the giant trees that tower over everything.", "Cutting and burning forests harms the animals, the people who live there and the planet's climate."], ex: { t: "Forest in a jar", m: "a large glass jar with a lid, pebbles, soil, small plants or moss, a little water", p: ["Put a layer of pebbles at the bottom of the jar and soil on top.", "Plant the seedlings or moss and spray a little water.", "Close the jar and keep it somewhere bright but out of direct sun. The water evaporates, trickles down the glass and returns to the soil: it's a mini forest cycle!"] }, at: "Forest floors", m: "long paper, colored pencils", p: ["Draw a forest with four floors, from the ground to the top of the tallest trees.", "In each floor, put animals that live there: ants, jaguars, monkeys, macaws and harpy eagles.", "Draw the day 21 stamp in your passport."], q: "Which forest animal would you like to see up close?" },
es: { h: "El abuelo llevó a Nina y Leo a un parque con árboles tan altos que el cielo casi desaparecía. Estaba fresquito, húmedo y lleno de cantos de pájaros. “Imaginen un bosque así del tamaño de muchos países juntos”, dijo. “Esa es la Amazonía.”", t: "Los bosques", f: "Los bosques son el hogar de una enorme cantidad de plantas y animales. Las selvas tropicales, como la Amazonía, cubren una parte pequeña de la tierra del planeta, pero albergan más de la mitad de las especies terrestres conocidas. También guardan carbono, producen lluvia y protegen ríos y suelos.", x: "¡Un solo árbol grande de la Amazonía puede soltar cientos de litros de agua al aire en un día! Juntos, los árboles ayudan a que llueva en lugares muy lejanos.", s: ["La Amazonía es la selva tropical más grande del mundo y se extiende por nueve países.", "Los bosques tienen pisos: el suelo, los arbustos, las copas de los árboles y los árboles gigantes que sobresalen por encima de todo.", "Talar y quemar bosques perjudica a los animales, a las personas que viven en ellos y al clima del planeta."], ex: { t: "Bosque en un frasco", m: "un frasco de vidrio grande con tapa, piedritas, tierra, plantitas pequeñas o musgo, un poco de agua", p: ["Pon una capa de piedritas en el fondo del frasco y tierra encima.", "Planta las plantitas o el musgo y rocía un poco de agua.", "Cierra el frasco y déjalo en un lugar claro, pero sin sol directo. El agua se evapora, chorrea por el vidrio y vuelve a la tierra: ¡es un mini ciclo del bosque!"] }, at: "Pisos del bosque", m: "papel largo, lápices de colores", p: ["Dibuja un bosque con cuatro pisos, desde el suelo hasta la cima de los árboles más altos.", "Pon en cada piso animales que viven allí: hormigas, jaguares, monos, guacamayos y águilas arpías.", "Dibuja el sello del día 21 en el pasaporte."], q: "¿Qué animal del bosque te gustaría ver de cerca?" } },

{ e: "🐧", art: { b: "🐧", s: ["🐻‍❄️", "🧊", "❄️", "🦭"], c: ["#1B3A5A", "#8AC2E0"] },
pt: { h: "Leo desenhou um urso-polar abraçando um pinguim, e Nina caiu na risada. “Eles nunca iam se encontrar!”, disse. Leo ficou confuso. O vovô virou o globo: “O urso-polar vive aqui em cima, no Polo Norte. E o pinguim, lá embaixo, perto do Polo Sul.”", t: "Os polos", f: "Os polos são os lugares mais frios da Terra. O Polo Norte fica no meio de um oceano congelado, o Ártico. O Polo Sul fica num continente coberto de gelo, a Antártida. Os animais de lá têm camadas grossas de gordura e pelos ou penas para aguentar o frio.", x: "A temperatura mais baixa já medida na Terra foi registrada na Antártida: quase 90 graus abaixo de zero!", s: ["Os ursos-polares vivem só no Ártico, e quase todos os pinguins vivem no hemisfério sul.", "Na Antártida não mora ninguém de forma permanente: só cientistas que ficam por um tempo em estações de pesquisa, inclusive brasileiros.", "Debaixo do pelo branco, a pele do urso-polar é preta, o que ajuda a absorver o calor do Sol."], ex: { t: "Luva de gordura", m: "dois saquinhos plásticos com fecho, gordura vegetal ou manteiga, uma tigela com água e gelo, fita", p: ["Encha um saquinho com uma camada grossa de gordura. Coloque o outro saquinho dentro dele, de forma que a gordura fique entre os dois, e feche as bordas com fita.", "Coloque uma mão dentro do saquinho de gordura e mergulhe as duas mãos na água gelada.", "A mão “de gordura” quase não sente o frio! Focas, baleias e ursos-polares usam essa camada para se proteger."] }, at: "Polo Norte x Polo Sul", m: "papel, lápis de cor", p: ["Divida o papel em dois: Ártico de um lado, Antártida do outro.", "Desenhe em cada lado os animais certos: ursos-polares, focas e raposas-do-ártico de um lado; pinguins, focas e baleias do outro.", "Desenhe o selo do dia 22 no passaporte."], q: "Você aguentaria morar num lugar tão frio? O que levaria?" },
en: { h: "Leo drew a polar bear hugging a penguin, and Nina burst out laughing. “They'd never meet!” she said. Leo was confused. Grandpa turned the globe: “Polar bears live up here, near the North Pole. And penguins live way down there, near the South Pole.”", t: "The poles", f: "The poles are the coldest places on Earth. The North Pole is in the middle of a frozen ocean, the Arctic. The South Pole is on an ice-covered continent, Antarctica. The animals there have thick layers of fat and fur or feathers to withstand the cold.", x: "The lowest temperature ever measured on Earth was recorded in Antarctica: almost 90 degrees below zero Celsius (−128 °F)!", s: ["Polar bears live only in the Arctic, and almost all penguins live in the Southern Hemisphere.", "No one lives in Antarctica permanently: only scientists who stay for a while at research stations, including Brazilians.", "Under its white fur, a polar bear's skin is black, which helps it absorb the Sun's warmth."], ex: { t: "Blubber glove", m: "two zip-top plastic bags, vegetable shortening or butter, a bowl of ice water, tape", p: ["Fill one bag with a thick layer of shortening. Put the other bag inside it so the fat is sandwiched between them, and tape the edges closed.", "Put one hand inside the blubber bag and dip both hands into the ice water.", "The “blubber” hand barely feels the cold! Seals, whales and polar bears use this layer to protect themselves."] }, at: "North Pole vs. South Pole", m: "paper, colored pencils", p: ["Divide the paper in two: the Arctic on one side, Antarctica on the other.", "On each side, draw the right animals: polar bears, seals and Arctic foxes on one; penguins, seals and whales on the other.", "Draw the day 22 stamp in your passport."], q: "Could you handle living somewhere so cold? What would you bring?" },
es: { h: "Leo dibujó un oso polar abrazando a un pingüino, y Nina se murió de risa. “¡Nunca se encontrarían!”, dijo. Leo se confundió. El abuelo giró el globo: “El oso polar vive aquí arriba, en el Polo Norte. Y el pingüino, allá abajo, cerca del Polo Sur.”", t: "Los polos", f: "Los polos son los lugares más fríos de la Tierra. El Polo Norte está en medio de un océano congelado, el Ártico. El Polo Sur está en un continente cubierto de hielo, la Antártida. Los animales de allí tienen capas gruesas de grasa y pelo o plumas para aguantar el frío.", x: "¡La temperatura más baja medida en la Tierra se registró en la Antártida: casi 90 grados bajo cero!", s: ["Los osos polares viven solo en el Ártico, y casi todos los pingüinos viven en el hemisferio sur.", "En la Antártida no vive nadie de forma permanente: solo científicos que se quedan un tiempo en estaciones de investigación, incluso latinoamericanos.", "Debajo del pelaje blanco, la piel del oso polar es negra, lo que lo ayuda a absorber el calor del Sol."], ex: { t: "Guante de grasa", m: "dos bolsitas de plástico con cierre, grasa vegetal o manteca, un tazón con agua y hielo, cinta", p: ["Llena una bolsita con una capa gruesa de grasa. Mete la otra bolsita adentro, de modo que la grasa quede entre las dos, y cierra los bordes con cinta.", "Mete una mano dentro de la bolsita de grasa y sumerge las dos manos en el agua helada.", "¡La mano “de grasa” casi no siente el frío! Las focas, las ballenas y los osos polares usan esa capa para protegerse."] }, at: "Polo Norte vs. Polo Sur", m: "papel, lápices de colores", p: ["Divide el papel en dos: el Ártico de un lado, la Antártida del otro.", "Dibuja en cada lado los animales correctos: osos polares, focas y zorros árticos de un lado; pingüinos, focas y ballenas del otro.", "Dibuja el sello del día 22 en el pasaporte."], q: "¿Aguantarías vivir en un lugar tan frío? ¿Qué llevarías?" } },

{ e: "🐞", art: { b: "🐞", s: ["🦋", "🐜", "🌼", "🔍"], c: ["#3A4E0B", "#8AB02C"] },
pt: { h: "Nina colocou um bambolê no chão do quintal e desafiou Leo: “Aposto que tem mais de dez tipos de seres vivos aqui dentro!”. Leo achou impossível, mas com a lupa do vovô eles foram achando: formigas, uma joaninha, trevos, um tatuzinho… e muito mais.", t: "A vida na Terra", f: "A Terra está cheia de vida: plantas, animais, fungos e seres microscópicos, em todos os cantos, do fundo do mar ao alto das montanhas. Essa variedade de vida se chama biodiversidade. Todos os seres vivos dependem uns dos outros.", x: "Os cientistas já deram nome a mais de um milhão de espécies, mas acreditam que existam milhões de outras que ninguém descobriu ainda!", s: ["O Brasil é o país com mais espécies de plantas e animais do mundo.", "Os insetos são o grupo de animais com mais espécies conhecidas: só de besouros são centenas de milhares.", "Quando uma espécie desaparece para sempre, dizemos que ela foi extinta."], ex: { t: "Safári no quintal", m: "um bambolê ou barbante formando um círculo, uma lupa (se tiver), papel, lápis", p: ["Coloque o círculo no chão de um jardim, praça ou quintal.", "Procure, sem machucar nada, todos os seres vivos dentro do círculo: plantas, insetos, minhocas, fungos.", "Anote ou desenhe cada um. Quantos tipos diferentes você achou? Depois devolva tudo como estava."] }, at: "Teia da vida", m: "papel grande, lápis de cor, barbante (opcional)", p: ["Desenhe o Sol, uma planta, uma lagarta, um passarinho, um gavião e um cogumelo.", "Ligue com setas quem dá energia para quem: o Sol para a planta, a planta para a lagarta…", "Desenhe o selo do dia 23 no passaporte."], q: "Qual foi o ser vivo mais interessante que você encontrou no safári?" },
en: { h: "Nina laid a hula hoop on the backyard ground and challenged Leo: “I bet there are more than ten kinds of living things inside it!” Leo thought it was impossible, but with Grandpa's magnifying glass they kept finding them: ants, a ladybug, clover, a pill bug… and lots more.", t: "Life on Earth", f: "Earth is full of life: plants, animals, fungi and microscopic beings, in every corner, from the bottom of the sea to the tops of mountains. This variety of life is called biodiversity. All living things depend on each other.", x: "Scientists have named more than a million species, but they believe there are millions more that no one has discovered yet!", s: ["Brazil is the country with the most species of plants and animals in the world.", "Insects are the animal group with the most known species: there are hundreds of thousands of kinds of beetles alone.", "When a species disappears forever, we say it has gone extinct."], ex: { t: "Backyard safari", m: "a hula hoop or string laid in a circle, a magnifying glass (if you have one), paper, pencil", p: ["Put the circle on the ground in a garden, park or yard.", "Without harming anything, look for every living thing inside the circle: plants, insects, worms, fungi.", "Write down or draw each one. How many different kinds did you find? Afterward, leave everything as it was."] }, at: "Web of life", m: "large paper, colored pencils, string (optional)", p: ["Draw the Sun, a plant, a caterpillar, a little bird, a hawk and a mushroom.", "Connect them with arrows showing who gives energy to whom: Sun to plant, plant to caterpillar…", "Draw the day 23 stamp in your passport."], q: "What was the most interesting living thing you found on your safari?" },
es: { h: "Nina puso un aro en el suelo del patio y desafió a Leo: “¡Apuesto que adentro hay más de diez tipos de seres vivos!”. Leo creyó que era imposible, pero con la lupa del abuelo fueron encontrando: hormigas, una vaquita de San Antonio, tréboles, un bicho bolita… y mucho más.", t: "La vida en la Tierra", f: "La Tierra está llena de vida: plantas, animales, hongos y seres microscópicos, en todos los rincones, del fondo del mar a lo alto de las montañas. Esa variedad de vida se llama biodiversidad. Todos los seres vivos dependen unos de otros.", x: "¡Los científicos ya le pusieron nombre a más de un millón de especies, pero creen que existen millones más que nadie descubrió todavía!", s: ["Brasil es el país con más especies de plantas y animales del mundo.", "Los insectos son el grupo de animales con más especies conocidas: solo de escarabajos hay cientos de miles.", "Cuando una especie desaparece para siempre, decimos que se extinguió."], ex: { t: "Safari en el patio", m: "un aro o un cordel formando un círculo, una lupa (si tienes), papel, lápiz", p: ["Pon el círculo en el suelo de un jardín, plaza o patio.", "Busca, sin lastimar nada, todos los seres vivos dentro del círculo: plantas, insectos, lombrices, hongos.", "Anota o dibuja cada uno. ¿Cuántos tipos diferentes encontraste? Después deja todo como estaba."] }, at: "Red de la vida", m: "papel grande, lápices de colores, cordel (opcional)", p: ["Dibuja el Sol, una planta, una oruga, un pajarito, un halcón y un hongo.", "Une con flechas quién le da energía a quién: el Sol a la planta, la planta a la oruga…", "Dibuja el sello del día 23 en el pasaporte."], q: "¿Cuál fue el ser vivo más interesante que encontraste en el safari?" } },

{ e: "🐚", art: { b: "🐚", s: ["🦴", "🦕", "🪨", "🔍"], c: ["#4E3A1B", "#B08A4A"] },
pt: { h: "Numa loja de museu, Leo segurou uma pedra com o desenho perfeito de uma concha. “Alguém desenhou isso?”, perguntou. “A natureza desenhou, há milhões de anos”, respondeu o vovô. “É um fóssil, uma mensagem que a Terra guardou para a gente ler hoje.”", t: "Fósseis: o diário da Terra", f: "Fósseis são restos ou marcas de seres vivos muito antigos, como ossos, conchas, folhas e até pegadas, que ficaram presos nas rochas. Quando um animal ou planta era coberto por lama ou areia, aos poucos minerais tomavam o lugar dele e viravam pedra.", x: "Na Chapada do Araripe, no Ceará, existem fósseis tão bem conservados que dá para ver peixes inteiros, insetos e até penas de animais que viveram há mais de 100 milhões de anos!", s: ["Os cientistas que estudam fósseis se chamam paleontólogos.", "Os fósseis mostram que a Terra já foi muito diferente, com mares onde hoje há montanhas.", "Alguns insetos ficaram presos em âmbar, uma resina de árvore, e se conservaram por milhões de anos."], ex: { t: "Fóssil de massinha", m: "massinha ou massa de sal, conchas, folhas, um brinquedo de dinossauro, gesso ou cola branca (opcional)", p: ["Achate uma bola de massinha como uma panqueca grossa.", "Aperte uma concha, uma folha ou a pata do dinossauro na massa e tire com cuidado.", "Ficou a marca: é um molde, como os fósseis! Se tiver gesso, um adulto pode encher a marca para fazer uma cópia."] }, at: "Diário da Terra em camadas", m: "papel, lápis de cor", p: ["Desenhe camadas de rocha empilhadas, como um bolo.", "Coloque fósseis em cada camada: os mais antigos embaixo, como trilobitas, e os mais novos em cima, como mamutes.", "Desenhe o selo do dia 24 no passaporte."], q: "Se um cientista do futuro achasse o seu fóssil, o que descobriria sobre você?" },
en: { h: "In a museum shop, Leo held a stone with a perfect picture of a shell on it. “Did someone draw this?” he asked. “Nature drew it, millions of years ago,” Grandpa answered. “It's a fossil, a message the Earth saved for us to read today.”", t: "Fossils: Earth's diary", f: "Fossils are the remains or traces of very ancient living things, like bones, shells, leaves and even footprints, preserved in rock. When an animal or plant was covered by mud or sand, minerals slowly took its place and turned it to stone.", x: "In the Araripe Plateau, in the Brazilian state of Ceará, there are fossils so well preserved that you can see whole fish, insects and even feathers of animals that lived more than 100 million years ago!", s: ["Scientists who study fossils are called paleontologists.", "Fossils show that Earth was once very different, with seas where there are mountains today.", "Some insects got trapped in amber, a tree resin, and were preserved for millions of years."], ex: { t: "Play dough fossil", m: "play dough or salt dough, shells, leaves, a toy dinosaur, plaster or white glue (optional)", p: ["Flatten a ball of dough into a thick pancake.", "Press a shell, a leaf or the dinosaur's foot into the dough and lift it out carefully.", "The print remains: it's a mold, like fossils! If you have plaster, a grown-up can fill the print to make a cast."] }, at: "Earth's diary in layers", m: "paper, colored pencils", p: ["Draw layers of rock stacked like a cake.", "Put fossils in each layer: the oldest at the bottom, like trilobites, and the newest on top, like mammoths.", "Draw the day 24 stamp in your passport."], q: "If a future scientist found your fossil, what would they learn about you?" },
es: { h: "En la tienda de un museo, Leo sostuvo una piedra con el dibujo perfecto de una concha. “¿Alguien dibujó esto?”, preguntó. “Lo dibujó la naturaleza, hace millones de años”, respondió el abuelo. “Es un fósil, un mensaje que la Tierra guardó para que lo leamos hoy.”", t: "Fósiles: el diario de la Tierra", f: "Los fósiles son restos o marcas de seres vivos muy antiguos, como huesos, conchas, hojas y hasta huellas, que quedaron atrapados en las rocas. Cuando un animal o una planta quedaba cubierto de barro o arena, poco a poco los minerales ocupaban su lugar y se volvían piedra.", x: "¡En la Chapada do Araripe, en el estado de Ceará, Brasil, hay fósiles tan bien conservados que se pueden ver peces enteros, insectos y hasta plumas de animales que vivieron hace más de 100 millones de años!", s: ["Los científicos que estudian los fósiles se llaman paleontólogos.", "Los fósiles muestran que la Tierra fue muy diferente, con mares donde hoy hay montañas.", "Algunos insectos quedaron atrapados en ámbar, una resina de árbol, y se conservaron durante millones de años."], ex: { t: "Fósil de plastilina", m: "plastilina o masa de sal, conchas, hojas, un dinosaurio de juguete, yeso o cola vinílica (opcional)", p: ["Aplasta una bola de masa como un panqueque grueso.", "Aprieta una concha, una hoja o la pata del dinosaurio en la masa y sácala con cuidado.", "Quedó la marca: ¡es un molde, como los fósiles! Si tienes yeso, un adulto puede rellenar la marca para hacer una copia."] }, at: "Diario de la Tierra en capas", m: "papel, lápices de colores", p: ["Dibuja capas de roca apiladas, como una torta.", "Pon fósiles en cada capa: los más antiguos abajo, como trilobites, y los más nuevos arriba, como mamuts.", "Dibuja el sello del día 24 en el pasaporte."], q: "Si un científico del futuro encontrara tu fósil, ¿qué descubriría sobre ti?" } },

{ e: "🗺️", art: { b: "🗺️", s: ["🧭", "🍊", "🌐", "📍"], c: ["#1B3A5A", "#4A8AC2"] },
pt: { h: "Leo comparou o mapa da parede com o globo e ficou intrigado: no mapa, a Groenlândia parecia do tamanho da África, mas no globo era bem menor. “O mapa está mentindo?”, perguntou. O vovô pegou uma laranja: “Não exatamente. É que é impossível achatar uma bola sem esticar alguma coisa.”", t: "Mapas e globos", f: "O globo é o jeito mais fiel de mostrar a Terra, porque é redondo como ela. Os mapas são planos, então sempre esticam ou apertam alguma parte. Para encontrar qualquer lugar, usamos linhas imaginárias: a linha do Equador divide a Terra ao meio, e os meridianos vão de polo a polo.", x: "A linha do Equador passa pelo Brasil! Em Macapá, no Amapá, existe um estádio de futebol em que a linha do meio do campo fica bem em cima do Equador: cada time joga num hemisfério!", s: ["A Groenlândia parece enorme em muitos mapas, mas a África é cerca de 14 vezes maior.", "O GPS do celular descobre onde você está conversando com satélites no espaço.", "Antigamente, os mapas eram desenhados à mão por exploradores e podiam ter monstros marinhos nas partes desconhecidas!"], ex: { t: "Mapa de casca de laranja", m: "uma laranja, uma caneta, um prato", p: ["Desenhe na laranja um continente bem simples e a linha do Equador.", "Descasque a laranja com cuidado, tentando manter a casca em poucos pedaços.", "Tente deixar a casca plana no prato: ela rasga e estica! Os desenhos ficam deformados, igual aos mapas planos. Depois coma a laranja!"] }, at: "Mapa do tesouro", m: "papel, lápis de cor, um “tesouro” pequeno", p: ["Esconda um tesouro em casa e desenhe um mapa com rosa dos ventos, legenda e um X.", "Desafie alguém a encontrar o tesouro só com o mapa.", "Desenhe o selo do dia 25 no passaporte."], q: "Se você desenhasse um mapa do seu bairro, o que não poderia faltar?" },
en: { h: "Leo compared the wall map with the globe and was puzzled: on the map, Greenland looked as big as Africa, but on the globe it was much smaller. “Is the map lying?” he asked. Grandpa grabbed an orange: “Not exactly. It's just impossible to flatten a ball without stretching something.”", t: "Maps and globes", f: "A globe is the most accurate way to show Earth, because it's round like Earth. Maps are flat, so they always stretch or squeeze some part. To find any place, we use imaginary lines: the equator splits Earth in half, and meridians run from pole to pole.", x: "The equator crosses Brazil! In Macapá, in the state of Amapá, there's a soccer stadium where the halfway line sits right on the equator: each team plays in a different hemisphere!", s: ["Greenland looks huge on many maps, but Africa is about 14 times bigger.", "A phone's GPS figures out where you are by talking to satellites in space.", "Long ago, maps were drawn by hand by explorers and sometimes had sea monsters in the unknown parts!"], ex: { t: "Orange peel map", m: "an orange, a pen, a plate", p: ["Draw a very simple continent and the equator on the orange.", "Peel the orange carefully, trying to keep the peel in a few big pieces.", "Try to lay the peel flat on the plate: it tears and stretches! The drawings get distorted, just like flat maps. Then eat the orange!"] }, at: "Treasure map", m: "paper, colored pencils, a small “treasure”", p: ["Hide a treasure at home and draw a map with a compass rose, a legend and an X.", "Challenge someone to find the treasure using only the map.", "Draw the day 25 stamp in your passport."], q: "If you drew a map of your neighborhood, what would it have to include?" },
es: { h: "Leo comparó el mapa de la pared con el globo y se quedó intrigado: en el mapa, Groenlandia parecía del tamaño de África, pero en el globo era mucho más chica. “¿El mapa miente?”, preguntó. El abuelo tomó una naranja: “No exactamente. Es que es imposible aplanar una pelota sin estirar algo.”", t: "Mapas y globos", f: "El globo es la forma más fiel de mostrar la Tierra, porque es redondo como ella. Los mapas son planos, así que siempre estiran o aprietan alguna parte. Para encontrar cualquier lugar usamos líneas imaginarias: la línea del ecuador divide la Tierra por la mitad, y los meridianos van de polo a polo.", x: "¡La línea del ecuador pasa por Brasil! En Macapá, en el estado de Amapá, hay un estadio de fútbol donde la línea del medio de la cancha está justo sobre el ecuador: ¡cada equipo juega en un hemisferio!", s: ["Groenlandia parece enorme en muchos mapas, pero África es unas 14 veces más grande.", "El GPS del celular descubre dónde estás comunicándose con satélites en el espacio.", "¡Antiguamente, los mapas los dibujaban a mano los exploradores y podían tener monstruos marinos en las partes desconocidas!"], ex: { t: "Mapa de cáscara de naranja", m: "una naranja, un bolígrafo, un plato", p: ["Dibuja en la naranja un continente bien simple y la línea del ecuador.", "Pela la naranja con cuidado, intentando dejar la cáscara en pocos pedazos.", "Intenta dejar la cáscara plana en el plato: ¡se rompe y se estira! Los dibujos quedan deformados, igual que en los mapas planos. ¡Después cómete la naranja!"] }, at: "Mapa del tesoro", m: "papel, lápices de colores, un “tesoro” pequeño", p: ["Esconde un tesoro en casa y dibuja un mapa con rosa de los vientos, leyenda y una X.", "Desafía a alguien a encontrar el tesoro solo con el mapa.", "Dibuja el sello del día 25 en el pasaporte."], q: "Si dibujaras un mapa de tu barrio, ¿qué no podría faltar?" } },

{ e: "👨‍👩‍👧‍👦", art: { b: "🧑‍🤝‍🧑", s: ["🌏", "🏙️", "🗣️", "🏡"], c: ["#4E1B3A", "#C24A8A"] },
pt: { h: "Nina perguntou quantas pessoas moram no mundo. “Mais de 8 bilhões”, disse o vovô. Leo tentou contar até um bilhão e desistiu no 47. O vovô riu e pegou um pote de feijões: “Vamos imaginar que o mundo inteiro fosse uma vila de só 100 pessoas.”", t: "As pessoas do planeta", f: "Mais de 8 bilhões de pessoas vivem na Terra, em cerca de 195 países. Falamos uns 7 mil idiomas diferentes, comemos comidas diferentes e temos costumes diferentes, mas todos precisamos das mesmas coisas: água, comida, um lar, saúde e carinho.", x: "Se o mundo fosse uma vila de 100 pessoas, cerca de 59 morariam na Ásia, 18 na África, 9 na Europa, 8 na América Latina, 5 na América do Norte e 1 na Oceania!", s: ["Hoje, mais da metade das pessoas do mundo vive em cidades.", "Os países com mais habitantes são a Índia e a China, cada um com mais de 1,4 bilhão de pessoas.", "O Brasil tem mais de 200 milhões de habitantes e está entre os países mais populosos do mundo."], ex: { t: "A vila de 100 pessoas", m: "100 feijões, grãos de milho ou botões, 6 potinhos ou pedaços de papel, canetinha", p: ["Escreva o nome de um continente em cada potinho: Ásia, África, Europa, América Latina, América do Norte e Oceania.", "Distribua os feijões: 59, 18, 9, 8, 5 e 1.", "Compare os potinhos. Onde mora mais gente? E onde mora menos? Você esperava isso?"] }, at: "Olá em muitas línguas", m: "papel, lápis de cor", p: ["Com um adulto, descubra como se diz “olá” em 5 idiomas diferentes.", "Desenhe 5 crianças de lugares diferentes, cada uma com um balão de fala.", "Desenhe o selo do dia 26 no passaporte."], q: "O que você gostaria de perguntar para uma criança de outro continente?" },
en: { h: "Nina asked how many people live in the world. “More than 8 billion,” said Grandpa. Leo tried counting to a billion and gave up at 47. Grandpa laughed and grabbed a jar of beans: “Let's imagine the whole world was a village of just 100 people.”", t: "The people of the planet", f: "More than 8 billion people live on Earth, in about 195 countries. We speak around 7,000 different languages, eat different foods and have different customs, but we all need the same things: water, food, a home, health and love.", x: "If the world were a village of 100 people, about 59 would live in Asia, 18 in Africa, 9 in Europe, 8 in Latin America, 5 in North America and 1 in Oceania!", s: ["Today, more than half the world's people live in cities.", "The countries with the most people are India and China, each with more than 1.4 billion.", "Brazil has more than 200 million people and is one of the most populous countries in the world."], ex: { t: "The village of 100", m: "100 beans, corn kernels or buttons, 6 small cups or pieces of paper, a marker", p: ["Write a continent on each cup: Asia, Africa, Europe, Latin America, North America and Oceania.", "Divide up the beans: 59, 18, 9, 8, 5 and 1.", "Compare the cups. Where do the most people live? The fewest? Did you expect that?"] }, at: "Hello in many languages", m: "paper, colored pencils", p: ["With a grown-up, find out how to say “hello” in 5 different languages.", "Draw 5 kids from different places, each with a speech bubble.", "Draw the day 26 stamp in your passport."], q: "What would you like to ask a kid from another continent?" },
es: { h: "Nina preguntó cuántas personas viven en el mundo. “Más de 8.000 millones”, dijo el abuelo. Leo intentó contar hasta mil millones y se rindió en el 47. El abuelo se rió y tomó un frasco de frijoles: “Imaginemos que el mundo entero fuera una aldea de solo 100 personas.”", t: "Las personas del planeta", f: "Más de 8.000 millones de personas viven en la Tierra, en unos 195 países. Hablamos unos 7.000 idiomas diferentes, comemos comidas distintas y tenemos costumbres diferentes, pero todos necesitamos las mismas cosas: agua, comida, un hogar, salud y cariño.", x: "¡Si el mundo fuera una aldea de 100 personas, unas 59 vivirían en Asia, 18 en África, 9 en Europa, 8 en América Latina, 5 en América del Norte y 1 en Oceanía!", s: ["Hoy, más de la mitad de las personas del mundo vive en ciudades.", "Los países con más habitantes son la India y China, cada uno con más de 1.400 millones de personas.", "Brasil tiene más de 200 millones de habitantes y está entre los países más poblados del mundo."], ex: { t: "La aldea de 100 personas", m: "100 frijoles, granos de maíz o botones, 6 potecitos o papelitos, marcador", p: ["Escribe el nombre de un continente en cada potecito: Asia, África, Europa, América Latina, América del Norte y Oceanía.", "Reparte los frijoles: 59, 18, 9, 8, 5 y 1.", "Compara los potecitos. ¿Dónde vive más gente? ¿Y dónde menos? ¿Te lo esperabas?"] }, at: "Hola en muchos idiomas", m: "papel, lápices de colores", p: ["Con un adulto, descubre cómo se dice “hola” en 5 idiomas diferentes.", "Dibuja 5 niños de lugares distintos, cada uno con un globo de diálogo.", "Dibuja el sello del día 26 en el pasaporte."], q: "¿Qué te gustaría preguntarle a un niño de otro continente?" } },

{ e: "🛰️", art: { b: "🛰️", s: ["🌍", "🌕", "📷", "✨"], c: ["#0B0B2A", "#2A3A7A"] },
pt: { h: "O vovô mostrou uma foto famosa: a Terra nascendo atrás da Lua, tirada por astronautas. Depois mostrou outra, em que a Terra era só um pontinho azul no meio do escuro. “Essa foi tirada de muito, muito longe”, disse baixinho. Nina ficou um tempão olhando aquele pontinho.", t: "A Terra vista do espaço", f: "Ver a Terra do espaço mudou o jeito como as pessoas pensam sobre o planeta. Em 1968, astronautas fotografaram a Terra surgindo atrás da Lua. Em 1990, a sonda Voyager 1, a bilhões de quilômetros de distância, fotografou a Terra como um pálido pontinho azul.", x: "Os astronautas da Estação Espacial Internacional dão uma volta na Terra a cada 90 minutos, mais ou menos. Por isso eles veem uns 16 nasceres do sol por dia!", s: ["Do espaço, não se veem fronteiras entre os países: só terra, mar e nuvens.", "Muitos astronautas contam que, ao ver a Terra lá de cima, sentiram vontade de cuidar melhor do planeta.", "A Lua é bem menor que a Terra: caberiam umas 50 Luas dentro do nosso planeta."], ex: { t: "Terra e Lua em escala", m: "uma bola grande (de basquete ou o globo), uma bolinha pequena (de pingue-pongue ou tênis), uma fita métrica ou barbante", p: ["A bola grande é a Terra e a bolinha é a Lua, mais ou menos no tamanho certo.", "Meça quantos “Terras” cabem enfileiradas no chão: a Lua fica a uns 30 diâmetros da Terra de distância.", "Afaste a bolinha até essa distância. É muito mais longe do que parecia, não é?"] }, at: "Cartão-postal do espaço", m: "papel preto, lápis de cor ou giz", p: ["Desenhe a Terra vista do espaço, com nuvens, oceanos e continentes.", "Escreva uma mensagem de astronauta para quem está na Terra.", "Desenhe o selo do dia 27 no passaporte."], q: "O que você sentiria olhando a Terra lá do espaço?" },
en: { h: "Grandpa showed a famous photo: the Earth rising behind the Moon, taken by astronauts. Then he showed another, where Earth was just a tiny blue dot in the dark. “This one was taken from very, very far away,” he said softly. Nina stared at that little dot for a long time.", t: "Earth seen from space", f: "Seeing Earth from space changed how people think about the planet. In 1968, astronauts photographed Earth rising behind the Moon. In 1990, the Voyager 1 probe, billions of kilometers away, photographed Earth as a pale blue dot.", x: "Astronauts on the International Space Station circle the Earth about every 90 minutes. That's why they see around 16 sunrises a day!", s: ["From space you can't see borders between countries: just land, sea and clouds.", "Many astronauts say that seeing Earth from up there made them want to take better care of the planet.", "The Moon is much smaller than Earth: about 50 Moons would fit inside our planet."], ex: { t: "Earth and Moon to scale", m: "a big ball (a basketball or the globe), a small ball (ping-pong or tennis ball), a tape measure or string", p: ["The big ball is Earth and the small ball is the Moon, roughly the right sizes.", "Measure how many “Earths” fit in a row on the floor: the Moon is about 30 Earth-widths away.", "Move the small ball to that distance. It's much farther than it seemed, isn't it?"] }, at: "Postcard from space", m: "black paper, colored pencils or chalk", p: ["Draw Earth seen from space, with clouds, oceans and continents.", "Write a message from an astronaut to the people on Earth.", "Draw the day 27 stamp in your passport."], q: "What would you feel looking at Earth from space?" },
es: { h: "El abuelo mostró una foto famosa: la Tierra saliendo detrás de la Luna, tomada por astronautas. Después mostró otra, en la que la Tierra era solo un puntito azul en medio de la oscuridad. “Esta se tomó desde muy, muy lejos”, dijo bajito. Nina se quedó un largo rato mirando ese puntito.", t: "La Tierra vista desde el espacio", f: "Ver la Tierra desde el espacio cambió la forma en que las personas piensan sobre el planeta. En 1968, unos astronautas fotografiaron la Tierra saliendo detrás de la Luna. En 1990, la sonda Voyager 1, a miles de millones de kilómetros, fotografió la Tierra como un pálido puntito azul.", x: "¡Los astronautas de la Estación Espacial Internacional dan una vuelta a la Tierra cada 90 minutos, más o menos! Por eso ven unos 16 amaneceres por día.", s: ["Desde el espacio no se ven fronteras entre países: solo tierra, mar y nubes.", "Muchos astronautas cuentan que, al ver la Tierra desde allá arriba, sintieron ganas de cuidar mejor el planeta.", "La Luna es mucho más chica que la Tierra: cabrían unas 50 Lunas dentro de nuestro planeta."], ex: { t: "Tierra y Luna a escala", m: "una pelota grande (de básquet o el globo), una pelotita pequeña (de ping-pong o tenis), una cinta métrica o cordel", p: ["La pelota grande es la Tierra y la pelotita es la Luna, más o menos del tamaño correcto.", "Mide cuántas “Tierras” caben en fila en el piso: la Luna está a unos 30 diámetros de la Tierra.", "Aleja la pelotita hasta esa distancia. ¿Es mucho más lejos de lo que parecía, no?"] }, at: "Postal desde el espacio", m: "papel negro, lápices de colores o tiza", p: ["Dibuja la Tierra vista desde el espacio, con nubes, océanos y continentes.", "Escribe un mensaje de astronauta para quienes están en la Tierra.", "Dibuja el sello del día 27 en el pasaporte."], q: "¿Qué sentirías mirando la Tierra desde el espacio?" } },

{ e: "🌡️", art: { b: "🌡️", s: ["🏭", "🚗", "🧊", "🌍"], c: ["#5A1B1B", "#E0603A"] },
pt: { h: "Nina ouviu no jornal que o planeta está esquentando e ficou preocupada. O vovô sentou do lado dela: “É verdade, e é um problema sério. Mas sabe o que é bom? Muita gente está trabalhando para resolver. E entender o problema é o primeiro passo.”", t: "O planeta está esquentando", f: "Alguns gases da atmosfera, como o gás carbônico, funcionam como um cobertor que segura o calor do Sol. Isso é natural e necessário. Mas, ao queimar muito carvão, petróleo e gás e derrubar florestas, os humanos engrossaram esse cobertor, e a Terra está esquentando mais rápido do que o normal.", x: "A temperatura média da Terra já subiu mais de 1 grau desde o fim dos anos 1800. Parece pouco, mas é suficiente para derreter geleiras, subir o nível do mar e deixar o tempo mais extremo!", s: ["Esse aquecimento é chamado de mudança climática ou aquecimento global.", "As florestas ajudam porque as árvores tiram gás carbônico do ar enquanto crescem.", "Energia do sol e do vento, transporte público, bicicletas e menos desperdício ajudam a diminuir o problema."], ex: { t: "Cobertor de plástico", m: "dois potes de vidro iguais, dois cubos de gelo iguais, filme plástico, um lugar ao sol", p: ["Coloque um cubo de gelo em cada pote.", "Cubra um dos potes com filme plástico e deixe o outro aberto.", "Deixe os dois no sol e veja qual derrete primeiro. O plástico segura o calor, como os gases que esquentam a Terra."] }, at: "Mural de soluções", m: "cartolina, lápis de cor", p: ["Desenhe a Terra no meio de uma cartolina.", "Em volta, desenhe 6 soluções: plantar árvores, andar de bicicleta, energia solar, desligar luzes, reciclar e não desperdiçar comida.", "Desenhe o selo do dia 28 no passaporte."], q: "Qual solução para o planeta você e sua família podem começar hoje?" },
en: { h: "Nina heard on the news that the planet is heating up and got worried. Grandpa sat down next to her: “It's true, and it's a serious problem. But you know what's good? Lots of people are working to solve it. And understanding the problem is the first step.”", t: "The planet is warming", f: "Some gases in the atmosphere, like carbon dioxide, work like a blanket that holds in the Sun's heat. That's natural and necessary. But by burning lots of coal, oil and gas and cutting down forests, humans have thickened that blanket, and Earth is warming faster than normal.", x: "Earth's average temperature has already risen more than 1 degree Celsius since the late 1800s. It sounds small, but it's enough to melt glaciers, raise sea levels and make weather more extreme!", s: ["This warming is called climate change or global warming.", "Forests help because trees pull carbon dioxide out of the air as they grow.", "Solar and wind power, public transit, bikes and less waste all help shrink the problem."], ex: { t: "Plastic blanket", m: "two identical glass jars, two equal ice cubes, plastic wrap, a sunny spot", p: ["Put an ice cube in each jar.", "Cover one jar with plastic wrap and leave the other open.", "Leave both in the sun and see which melts first. The plastic holds in heat, like the gases warming the Earth."] }, at: "Solutions mural", m: "poster board, colored pencils", p: ["Draw the Earth in the middle of the poster board.", "Around it, draw 6 solutions: planting trees, biking, solar energy, turning off lights, recycling and not wasting food.", "Draw the day 28 stamp in your passport."], q: "Which planet-saving solution can you and your family start today?" },
es: { h: "Nina escuchó en las noticias que el planeta se está calentando y se preocupó. El abuelo se sentó a su lado: “Es verdad, y es un problema serio. ¿Pero sabes qué es bueno? Mucha gente está trabajando para resolverlo. Y entender el problema es el primer paso.”", t: "El planeta se está calentando", f: "Algunos gases de la atmósfera, como el dióxido de carbono, funcionan como una manta que retiene el calor del Sol. Eso es natural y necesario. Pero al quemar mucho carbón, petróleo y gas y talar bosques, los humanos engrosaron esa manta, y la Tierra se está calentando más rápido de lo normal.", x: "¡La temperatura promedio de la Tierra ya subió más de 1 grado desde fines del siglo XIX! Parece poco, pero alcanza para derretir glaciares, subir el nivel del mar y hacer el clima más extremo.", s: ["Este calentamiento se llama cambio climático o calentamiento global.", "Los bosques ayudan porque los árboles sacan dióxido de carbono del aire mientras crecen.", "La energía solar y eólica, el transporte público, las bicicletas y menos desperdicio ayudan a reducir el problema."], ex: { t: "Manta de plástico", m: "dos frascos de vidrio iguales, dos cubitos de hielo iguales, film plástico, un lugar al sol", p: ["Pon un cubito de hielo en cada frasco.", "Cubre uno de los frascos con film plástico y deja el otro abierto.", "Deja los dos al sol y mira cuál se derrite primero. El plástico retiene el calor, como los gases que calientan la Tierra."] }, at: "Mural de soluciones", m: "cartulina, lápices de colores", p: ["Dibuja la Tierra en el medio de una cartulina.", "Alrededor, dibuja 6 soluciones: plantar árboles, andar en bicicleta, energía solar, apagar luces, reciclar y no desperdiciar comida.", "Dibuja el sello del día 28 en el pasaporte."], q: "¿Qué solución para el planeta pueden empezar hoy tú y tu familia?" } },

{ e: "♻️", art: { b: "♻️", s: ["🌱", "🚲", "🗑️", "💧"], c: ["#0B4E2A", "#2CB05A"] },
pt: { h: "Leo ia jogar uma garrafa no lixo comum, mas Nina segurou o braço dele. “Essa vai para a reciclagem!”, disse. O vovô sorriu, orgulhoso dos dois, e propôs uma missão: “Hoje vamos fazer bombas… de sementes! Para espalhar vida por aí.”", t: "Cuidando da nossa casa", f: "Cada pessoa pode ajudar o planeta com atitudes do dia a dia: reduzir o lixo, reutilizar o que dá e reciclar o resto. Economizar água e energia, plantar árvores, proteger os animais e não jogar lixo na rua também fazem muita diferença.", x: "Uma garrafa plástica pode levar centenas de anos para se desfazer na natureza! Por isso, o melhor lixo é aquele que nem chega a ser produzido.", s: ["Reciclar uma lata de alumínio economiza muita energia em comparação com fazer uma lata nova.", "Restos de frutas e verduras podem virar adubo numa composteira.", "Fechar a torneira enquanto escova os dentes pode economizar muitos litros de água por dia."], ex: { t: "Bombas de sementes", m: "terra, argila ou barro, sementes de flores ou ervas nativas, água, uma bandeja", p: ["Misture duas partes de terra com uma de argila e um pouquinho de água até dar para modelar.", "Coloque algumas sementes e faça bolinhas do tamanho de uma noz.", "Deixe secar um dia e depois jogue as bolinhas num canteiro, terreno ou vaso. Quando chover, as sementes brotam!"] }, at: "Os 3 Rs da minha casa", m: "papel, lápis de cor", p: ["Faça três colunas: Reduzir, Reutilizar e Reciclar.", "Escreva ou desenhe em cada coluna duas coisas que sua família pode fazer.", "Pendure na geladeira e desenhe o selo do dia 29 no passaporte."], q: "Que objeto da sua casa poderia ganhar uma segunda vida?" },
en: { h: "Leo was about to toss a bottle in the regular trash, but Nina stopped his arm. “That goes in recycling!” she said. Grandpa smiled, proud of both of them, and proposed a mission: “Today we'll make bombs… seed bombs! To spread life around.”", t: "Taking care of our home", f: "Everyone can help the planet with everyday actions: reduce trash, reuse what we can and recycle the rest. Saving water and energy, planting trees, protecting animals and not littering also make a big difference.", x: "A plastic bottle can take hundreds of years to break down in nature! That's why the best trash is the trash that never gets made.", s: ["Recycling an aluminum can saves a lot of energy compared to making a new one.", "Fruit and vegetable scraps can become fertilizer in a compost bin.", "Turning off the faucet while you brush your teeth can save many liters of water a day."], ex: { t: "Seed bombs", m: "soil, clay or mud, seeds of native flowers or herbs, water, a tray", p: ["Mix two parts soil with one part clay and a little water until you can shape it.", "Add a few seeds and roll balls about the size of a walnut.", "Let them dry for a day, then toss them into a flower bed, empty lot or pot. When it rains, the seeds sprout!"] }, at: "The 3 Rs at home", m: "paper, colored pencils", p: ["Make three columns: Reduce, Reuse and Recycle.", "Write or draw two things your family can do in each column.", "Stick it on the fridge and draw the day 29 stamp in your passport."], q: "What object in your house could get a second life?" },
es: { h: "Leo iba a tirar una botella en la basura común, pero Nina le agarró el brazo. “¡Esa va al reciclaje!”, dijo. El abuelo sonrió, orgulloso de los dos, y propuso una misión: “Hoy vamos a hacer bombas… ¡de semillas! Para esparcir vida por ahí.”", t: "Cuidando nuestra casa", f: "Cada persona puede ayudar al planeta con acciones de todos los días: reducir la basura, reutilizar lo que se pueda y reciclar el resto. Ahorrar agua y energía, plantar árboles, proteger a los animales y no tirar basura en la calle también hacen mucha diferencia.", x: "¡Una botella de plástico puede tardar cientos de años en deshacerse en la naturaleza! Por eso, la mejor basura es la que nunca se produce.", s: ["Reciclar una lata de aluminio ahorra mucha energía comparado con fabricar una lata nueva.", "Los restos de frutas y verduras pueden convertirse en abono en una compostera.", "Cerrar la canilla mientras te cepillas los dientes puede ahorrar muchos litros de agua por día."], ex: { t: "Bombas de semillas", m: "tierra, arcilla o barro, semillas de flores o hierbas nativas, agua, una bandeja", p: ["Mezcla dos partes de tierra con una de arcilla y un poquito de agua hasta que se pueda modelar.", "Agrega algunas semillas y haz bolitas del tamaño de una nuez.", "Déjalas secar un día y después tíralas en un cantero, un terreno o una maceta. ¡Cuando llueva, las semillas brotan!"] }, at: "Las 3 R de mi casa", m: "papel, lápices de colores", p: ["Haz tres columnas: Reducir, Reutilizar y Reciclar.", "Escribe o dibuja en cada columna dos cosas que tu familia puede hacer.", "Pégalo en la heladera y dibuja el sello del día 29 en el pasaporte."], q: "¿Qué objeto de tu casa podría tener una segunda vida?" } },

{ e: "🏅", art: { b: "🌍", s: ["🌱", "🌊", "🏔️", "🎉"], c: ["#14466B", "#2CA07A"] },
pt: { h: "Na última noite, o passaporte do planeta estava cheio de selos. Nina e Leo colocaram o globo no meio da mesa e cada um fez uma promessa para a Terra. O Pipoca deitou em cima do Brasil, como se também prometesse alguma coisa. “Agora vocês são Guardiões do Planeta”, disse o vovô.", t: "Guardiões do Planeta", f: "Em 30 dias, vocês viajaram do centro quente da Terra até o espaço, passando por rochas, solos, montanhas, oceanos, rios, geleiras, desertos, florestas e polos. A Terra é a nossa única casa, e tudo nela está ligado: o ar, a água, o solo e todos os seres vivos.", x: "As plantas soltam oxigênio quando recebem luz do Sol, e é graças a elas e às algas do mar que conseguimos respirar!", s: ["A Terra tem bilhões de anos, mas os humanos estão aqui há bem pouco tempo.", "Cada atitude, por menor que seja, ajuda a cuidar do planeta.", "Cientistas, crianças, comunidades e governos do mundo todo estão juntos nessa missão."], ex: { t: "A folha que respira", m: "uma folha verde e fresquinha (recém-colhida), uma tigela transparente com água, uma pedrinha, sol", p: ["Coloque a folha dentro da tigela de água e segure-a no fundo com a pedrinha.", "Deixe a tigela no sol por uma ou duas horas.", "Olhe de perto: aparecem bolhinhas na folha! É o oxigênio que a planta produz com a luz do Sol. O planeta está respirando."] }, at: "Carta para a Terra", m: "papel bonito, lápis de cor, envelope", p: ["Escreva uma carta para a Terra contando o que você mais aprendeu e o que promete fazer por ela.", "Enfeite com desenhos de tudo o que você explorou nesses 30 dias.", "Guarde a carta no passaporte junto com o último selo: Guardião do Planeta!"], q: "Qual promessa você faz para a Terra hoje?" },
en: { h: "On the last night, the planet passport was full of stamps. Nina and Leo set the globe in the middle of the table, and each made a promise to the Earth. Popcorn lay down on top of Brazil, as if he were promising something too. “Now you're Planet Guardians,” Grandpa said.", t: "Planet Guardians", f: "In 30 days, you traveled from Earth's hot center to outer space, through rocks, soil, mountains, oceans, rivers, glaciers, deserts, forests and poles. Earth is our only home, and everything on it is connected: air, water, soil and every living thing.", x: "Plants release oxygen when they get sunlight, and thanks to them and the algae in the sea, we can breathe!", s: ["Earth is billions of years old, but humans have been here for only a very short time.", "Every action, no matter how small, helps care for the planet.", "Scientists, kids, communities and governments around the world are on this mission together."], ex: { t: "The breathing leaf", m: "a fresh green leaf (just picked), a clear bowl of water, a small stone, sunshine", p: ["Put the leaf in the bowl of water and hold it at the bottom with the stone.", "Leave the bowl in the sun for an hour or two.", "Look closely: little bubbles appear on the leaf! That's oxygen the plant makes with sunlight. The planet is breathing."] }, at: "A letter to the Earth", m: "nice paper, colored pencils, an envelope", p: ["Write a letter to the Earth telling it what you learned most and what you promise to do for it.", "Decorate it with drawings of everything you explored in these 30 days.", "Keep the letter in your passport with the last stamp: Planet Guardian!"], q: "What promise do you make to the Earth today?" },
es: { h: "En la última noche, el pasaporte del planeta estaba lleno de sellos. Nina y Leo pusieron el globo en el medio de la mesa y cada uno le hizo una promesa a la Tierra. Palomita se acostó encima de Brasil, como si también prometiera algo. “Ahora son Guardianes del Planeta”, dijo el abuelo.", t: "Guardianes del Planeta", f: "En 30 días viajaron desde el centro caliente de la Tierra hasta el espacio, pasando por rocas, suelos, montañas, océanos, ríos, glaciares, desiertos, bosques y polos. La Tierra es nuestra única casa, y todo en ella está conectado: el aire, el agua, el suelo y todos los seres vivos.", x: "¡Las plantas sueltan oxígeno cuando reciben la luz del Sol, y gracias a ellas y a las algas del mar podemos respirar!", s: ["La Tierra tiene miles de millones de años, pero los humanos estamos aquí hace muy poco tiempo.", "Cada acción, por más pequeña que sea, ayuda a cuidar el planeta.", "Científicos, niños, comunidades y gobiernos de todo el mundo están juntos en esta misión."], ex: { t: "La hoja que respira", m: "una hoja verde y fresca (recién cortada), un tazón transparente con agua, una piedrita, sol", p: ["Pon la hoja dentro del tazón con agua y sujétala en el fondo con la piedrita.", "Deja el tazón al sol una o dos horas.", "Mira de cerca: ¡aparecen burbujitas en la hoja! Es el oxígeno que la planta produce con la luz del Sol. El planeta está respirando."] }, at: "Carta para la Tierra", m: "papel lindo, lápices de colores, un sobre", p: ["Escribe una carta para la Tierra contándole lo que más aprendiste y lo que prometes hacer por ella.", "Decórala con dibujos de todo lo que exploraste en estos 30 días.", "Guarda la carta en el pasaporte junto con el último sello: ¡Guardián del Planeta!"], q: "¿Qué promesa le haces hoy a la Tierra?" } },
];
